import sys
from collections import Counter

def solve():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    q = int(data[1])

    coins = [int(data[i+2]) for i in range(n)]
    queries = [int(data[n+2+i]) for i in range(q)]

    coin_counts = Counter(coins)
    unique_coins = sorted(set(coins))

    results = []

    for query in queries:
        if query in coin_counts:
            results.append(1)
            continue

        dp = [float('inf')] * (query + 1)
        dp[0] = 0

        for coin in unique_coins:
            for value in range(coin, query + 1):
                dp[value] = min(dp[value], dp[value - coin] + 1)

        if dp[query] == float('inf'):
            results.append(-1)
        else:
            results.append(dp[query])

    for result in results:
        print(result)

if __name__ == "__main__":
    solve()

import sys
from collections import Counter

def min_coins_to_value(n, q, coins, queries):
    coin_counts = Counter(coins)
    unique_powers_of_two = sorted(coin_counts.keys())

    results = []
    for b in queries:
        if b not in coin_counts and b not in unique_powers_of_two:
            # Check if b can be formed using a subset of available coins
            sum_powers_of_two = 0
            min_coins = float('inf')
            for power in reversed(unique_powers_of_two):
                if sum_powers_of_two >= b:
                    break
                if b & power:  # if power is a part of b
                    needed = (b // power) - (1 if sum_powers_of_two + power * ((b // power)) == b else 0)
                    if power in coin_counts:
                        min_coins = min(min_coins, needed)
                    else:
                        min_coins = min(min_coins, needed + 1)
                    sum_powers_of_two += power * ((b // power))

            if sum_powers_of_two < b:
                results.append(-1)
            else:
                results.append(min_coins)
        else:
            results.append(1)

    return results

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    q = int(data[1])

    coins = list(map(int, data[2:n + 2]))

    queries = list(map(int, data[n + 2:n + 2 + q]))

    results = min_coins_to_value(n, q, coins, queries)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
